export function loadTemplates() {
    const templates = {};
    for (let n = 1; n <= 15; n++) {
        templates[n] = EMBEDDED_TEMPLATES[n] || null;
    }
    return templates;
}

export function fillTemplate(templateXml, tableDisplay, columns) {
    let xml = templateXml;
    // Only append "表" if tableDisplay doesn't already end with "表"
    const display = tableDisplay.endsWith('表') ? tableDisplay : tableDisplay + '表';
    xml = xml.replace(/value="[^"]*表"/, 'value="' + display + '"');
    for (let i = 0; i < columns.length; i++) {
        var regex = new RegExp('value="' + (i + 1) + '"');
        xml = xml.replace(regex, 'value="' + columns[i].display + '"');
    }
    return xml;
}
